class Solution {
    public String minWindow(String s, String t) {
        int[] required = new int[128];
        for (int index = 0; index < t.length(); index++) required[t.charAt(index)]++;
        int bestStart = 0;
        int bestLength = Integer.MAX_VALUE;
        for (int start = 0; start < s.length(); start++) {
            int[] found = new int[128];
            int matched = 0;
            for (int end = start; end < s.length(); end++) {
                char value = s.charAt(end);
                if (found[value] < required[value]) matched++;
                found[value]++;
                if (matched == t.length()) {
                    int length = end - start + 1;
                    if (length < bestLength) {
                        bestLength = length;
                        bestStart = start;
                    }
                    break;
                }
            }
        }
        return bestLength == Integer.MAX_VALUE ? s.substring(0, 0) : s.substring(bestStart, bestStart + bestLength);
    }
}

