class Solution {
    public String minWindow(String s, String t) {
        int[] need = new int[128];
        for (int index = 0; index < t.length(); index++) need[t.charAt(index)]++;
        int missing = t.length();
        int left = 0;
        int bestStart = 0;
        int bestLength = Integer.MAX_VALUE;
        for (int right = 0; right < s.length(); right++) {
            char added = s.charAt(right);
            if (need[added] > 0) missing--;
            need[added]--;
            while (missing == 0) {
                int length = right - left + 1;
                if (length < bestLength) {
                    bestLength = length;
                    bestStart = left;
                }
                char removed = s.charAt(left);
                need[removed]++;
                left++;
                if (need[removed] > 0) missing++;
            }
        }
        return bestLength == Integer.MAX_VALUE ? s.substring(0, 0) : s.substring(bestStart, bestStart + bestLength);
    }
}
